-- Heroes of Battle spell definitions.
-- Source: Heroes of Battle, Chapter 6, pp. 123-129. Mechanical text is summarized; source pages remain authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('hob-3.5','heroes-of-battle-3-5','Heroes of Battle','HoB','Wizards of the Coast','dnd','3.5',
        'D&D 3.5 supplement for battlefield adventures, military characters, command, morale, and mass-conflict procedures.',NULL,1,0,NULL);

INSERT OR IGNORE INTO dnd35_spells
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,school_id,subschool,casting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,saving_throw_text,save,spell_resistance,spell_resistance_text) VALUES
  ('hob-spell-acid-rain','hob-3.5','124','acid-rain','Acid Rain','Creates an acidic downpour that deals 7d6 acid damage, then leaves slick ground that hampers movement.','Creatures in the cylinder take 7d6 acid damage with no save. The slick ground remains for caster level rounds; movement is halved unless a DC 10 Balance check succeeds, failure prevents movement for the round, and failure by 5 or more causes a fall.',0,NULL,1,'phb-spell-school-conjuration','Creation','1 standard action',NULL,'Long (400 ft. + 40 ft./level)',NULL,'20-ft.-radius cylinder, 40 ft. high',NULL,'1 full round and 1 round/level; see text','None',NULL,'no','No'),
  ('hob-spell-aerial-alarm','hob-3.5','124','aerial-alarm','Aerial Alarm','Functions as alarm for Medium or larger flying creatures entering a tall cylindrical ward.','Functions as alarm for Medium or larger flying creatures entering a tall cylindrical ward.',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 standard action',NULL,'Medium (100 ft. + 10 ft./level)',NULL,'100-ft.-radius cylinder, 500 ft. high',NULL,'2 hours/level (D)','None',NULL,'no','No'),
  ('hob-spell-animate-legion','hob-3.5','124','animate-legion','Animate Legion','Temporarily animates corpses as skeletons or zombies totaling up to twice caster level in Hit Dice.','Creates up to twice caster level in Hit Dice of skeletons or zombies for 1 round/level. They begin uncontrolled and attack the nearest living creatures unless otherwise influenced.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One or more corpses, no two more than 30 ft. apart',NULL,NULL,'1 round/level','None',NULL,'no','No'),
  ('hob-spell-animate-siege-weapon','hob-3.5','125','animate-siege-weapon','Animate Siege Weapon','Animates a siege weapon so it can operate and attack without a crew.','The affected siege weapon operates itself as a normal crew would, automatically succeeds on operating checks, and uses the caster level as its attack bonus. Commands can be changed as a free action while within range.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 round',NULL,'Close (25 ft. + 5 ft./2 levels)','One siege weapon of up to Gargantuan size',NULL,NULL,'1 round/level','None',NULL,'no','No'),
  ('hob-spell-battlefield-fortification','hob-3.5','125','battlefield-fortification','Battlefield Fortification','Shifts earth to create a shallow trench or berm useful as battlefield cover.','Creates a straight trench or berm up to 5 feet long per two caster levels; a berm is 2 squares wide. It has no effect on stone or similarly hard-paved ground.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 round',NULL,'Close (25 ft. + 5 ft./2 levels)',NULL,'See text',NULL,'Instantaneous','None',NULL,'no','No'),
  ('hob-spell-battlefield-illumination','hob-3.5','125','battlefield-illumination','Battlefield Illumination','Raises illumination in a large battlefield cylinder by one light category.','Improves illumination by one category without stacking with other magical light. It counters and dispels early twilight, but does not affect other darkness spells.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 round',NULL,'Long (400 ft. + 40 ft./level)',NULL,'80-ft.-radius cylinder, 40 ft. high',NULL,'10 minutes/level (D)','None',NULL,'no','No'),
  ('hob-spell-battlemagic-perception','hob-3.5','125','battlemagic-perception','Battlemagic Perception','Improves identification of spellcasting and can detect and counter nearby magic.','Grants +5 competence on Spellcraft checks to identify spells as they are cast. With 5 Spellcraft ranks, senses spells and spell-like abilities within 100 feet with line of effect; a DC 15 + spell level check identifies the spell and permits a free-action counterspell attempt, ending this spell if the counter succeeds.',0,NULL,1,'phb-spell-school-divination',NULL,'1 standard action',NULL,'Personal','You',NULL,NULL,'10 min./level (D)',NULL,NULL,'no','No'),
  ('hob-spell-blaze-of-light','hob-3.5','125','blaze-of-light','Blaze of Light','Projects brilliant light that dazzles creatures failing a Fortitude save for 1 minute.','Sighted creatures in the cone that fail a Fortitude save are dazzled for 1 minute. Sightless creatures are unaffected. As a light spell, it counters and dispels equal- or lower-level darkness spells.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 standard action',NULL,'60 ft.',NULL,'Cone',NULL,'Instantaneous','Fortitude negates','fort','yes','Yes'),
  ('hob-spell-boiling-oil','hob-3.5','125-126','boiling-oil','Boiling Oil','Rains scalding oil for 4d6 fire damage and continued damage to creatures that fail the initial save.','The initial torrent deals 4d6 fire damage, Reflex half. A creature that fails the initial save takes 2d6 additional fire damage each subsequent round of the duration, up to 6 rounds at caster level 18. The conjured oil is not flammable.',0,NULL,1,'phb-spell-school-conjuration','Creation','1 standard action',NULL,'Medium (100 ft. + 10 ft./level)',NULL,'10-ft.-radius cylinder, 40 ft. high',NULL,'1 round and 1 round/three levels; see text','Reflex half','ref','no','No'),
  ('hob-spell-consecrate-battlefield','hob-3.5','126','consecrate-battlefield','Consecrate Battlefield','Extends consecrate over a large battlefield and prevents corpses slain there from becoming undead during the duration.','Functions as consecrate over the larger area. A creature slain in the area cannot be turned into undead during the duration even if its corpse is removed. Counters and dispels desecrate and desecrate battlefield.',0,NULL,1,'phb-spell-school-evocation',NULL,'10 minutes',NULL,'Medium (100 ft. + 10 ft./level)',NULL,'100-ft.-radius emanation',NULL,'1 day/level',NULL,NULL,'no','No'),
  ('hob-spell-crisis-of-confidence','hob-3.5','126','crisis-of-confidence','Crisis of Confidence','Suppresses battlefield leadership, commander rating, commander auras, and Charisma contribution to rally checks.','The target cannot add Charisma to rally checks, its commander rating becomes 0, and it loses commander auras for the duration. Its commander rating, if any, adds as a bonus on the Will save.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 minute/level','Will negates','will','yes','Yes'),
  ('hob-spell-desecrate-battlefield','hob-3.5','126','desecrate-battlefield','Desecrate Battlefield','Extends desecrate over a large battlefield, empowering negative energy across the area.','Functions as desecrate over the larger area and counters or dispels consecrate and consecrate battlefield.',0,NULL,1,'phb-spell-school-evocation',NULL,'10 minutes',NULL,'Medium (100 ft. + 10 ft./level)',NULL,'100-ft.-radius emanation',NULL,'1 day/level',NULL,NULL,'no','No'),
  ('hob-spell-drums-of-war','hob-3.5','126','drums-of-war','Drums of War','Transforms a bardic performance into ominous drums that penalize enemies.','Enemies within range take a -2 penalty on attack rolls and saving throws while the performance continues and for 1 round/level afterward. Deaf creatures and creatures protected by silence are unaffected.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 standard action',NULL,'Medium (100 ft. + 10 ft./level)',NULL,NULL,NULL,'Concentration plus 1 round/level (D)','None',NULL,'yes','Yes'),
  ('hob-spell-early-twilight','hob-3.5','126','early-twilight','Early Twilight','Reduces illumination in a large battlefield cylinder by one category.','Reduces illumination by one category without stacking with other magical darkness. It counters and dispels battlefield illumination, but not other light spells.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 round',NULL,'Long (400 ft. + 40 ft./level)',NULL,'80-ft.-radius cylinder, 40 ft. high',NULL,'10 minutes/level (D)','None',NULL,'no','No'),
  ('hob-spell-hurtling-stone','hob-3.5','127','hurtling-stone','Hurtling Stone','Creates a 50-pound stone that tears through a line, dealing 6d6 damage and knocking smaller creatures prone.','Each creature in the 60-foot line takes 6d6 damage unless it succeeds on a Reflex save. Medium or smaller creatures hit are also knocked prone.',0,NULL,1,'phb-spell-school-conjuration','Creation','1 standard action',NULL,'60 ft.',NULL,'60-ft. line',NULL,'Instantaneous','Reflex negates','ref','no','No'),
  ('hob-spell-leomunds-billet','hob-3.5','127','leomunds-billet','Leomund’s Billet','Creates a temporary barracks structure equipped to house forty troops.','Creates a simple 20-by-80-foot billet with barred doors/windows, forty bunks, tables, stools, fireplaces, fuel, bread, and hot gruel. It provides no magical protection.',0,NULL,1,'phb-spell-school-conjuration','Creation','1 standard action',NULL,'Close (25 ft. + 5 ft./level)',NULL,NULL,'20-ft.-by-80-ft. structure','2 hours/level','None',NULL,'no','No'),
  ('hob-spell-molten-strike','hob-3.5','127','molten-strike','Molten Strike','Detonates molten rock for 2d6 fire damage and can set creatures on fire.','Creatures in the burst take 2d6 fire damage. A creature failing its Reflex save also catches fire and takes 1d6 fire damage each round until it succeeds on a DC 15 Reflex save to extinguish the flames.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 standard action',NULL,'Long (400 ft. + 40 ft./level)',NULL,'5-ft.-radius burst',NULL,'Instantaneous','Reflex negates','ref','yes','Yes'),
  ('hob-spell-resounding-voice','hob-3.5','127','resounding-voice','Resounding Voice','Makes the subject’s voice carry clearly to 100 feet per caster level.','The subject can be heard clearly out to 100 feet per caster level. Magical silence still blocks the voice. Resounding voice counters and dispels silence and is itself countered and dispelled by silence.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action',NULL,'Touch','Creature touched',NULL,NULL,'1 minute/level (D)','Will negates (harmless)','will','yes','Yes (harmless)'),
  ('hob-spell-shrieking-blast','hob-3.5','127','shrieking-blast','Shrieking Blast','Creates a deafening sonic explosion dealing 8d6 damage and potentially permanent deafness.','Creatures in the burst take 8d6 sonic damage and are permanently deafened. A successful Fortitude save halves the damage and reduces the deafness to 1 round.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 standard action',NULL,'Medium (100 ft. + 10 ft./level)',NULL,'40-ft.-radius burst',NULL,'Instantaneous','Fortitude partial; see text','fort','yes','Yes'),
  ('hob-spell-spiritual-cavalry','hob-3.5','127-128','spiritual-cavalry','Spiritual Cavalry','Creates multiple spiritual chargers that strike separate targets and can trample creatures prone.','Creates one force horseman per four caster levels, maximum five at 20th, with no more than one attacking each target. Each functions as spiritual charger; a Large or smaller creature hit must also make a Fortitude save or fall prone and take 1d8 extra force damage.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 standard action',NULL,'Medium (100 ft. + 10 ft./level)',NULL,NULL,'Two or more magical horsemen of force','Instantaneous','None and Fortitude negates; see text','fort','yes','Yes'),
  ('hob-spell-spiritual-charger','hob-3.5','128','spiritual-charger','Spiritual Charger','Creates a lance-wielding force rider that charges a designated target.','The rider attacks with caster base attack bonus + Wisdom modifier, gaining +2 if it can charge at least 10 feet. It deals 2d8 force damage +1 per three caster levels (maximum +5), threatens on a natural 20, and deals triple damage on a confirmed critical hit.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 standard action',NULL,'Medium (100 ft. + 10 ft./level)',NULL,NULL,'Magical horseman of force','Instantaneous','None',NULL,'yes','Yes'),
  ('hob-spell-status-greater','hob-3.5','128','status-greater','Status, Greater','Functions as status but monitors up to ten living creatures per caster level at medium range.','Functions as status but monitors up to ten living creatures per caster level at medium range.',0,NULL,1,'phb-spell-school-divination',NULL,'1 minute',NULL,'Medium (100 ft. + 10 ft./level)','Ten living creatures per caster level',NULL,NULL,'1 hour/level','Will negates (harmless)','will','yes','Yes (harmless)'),
  ('hob-spell-trip-vine','hob-3.5','128-129','trip-vine','Trip Vine','Entangles existing plants into tripping hazards across multiple squares.','A creature entering an affected square must make a Reflex save or fall prone. Charging creatures take -2 on the save; casting it over undergrowth imposes another -2 penalty as described by the spell.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action',NULL,'Medium (100 ft. + 10 ft./level)',NULL,'One 10-ft. square/level (S)',NULL,'1 hour/level','Reflex negates; see text','ref','no','No');
